function questionType(q) {
  const openers = ["who", "what", "why", "how", "tell me", "describe"];
  const lower = q.toLowerCase();
  return openers.some(o => lower.startsWith(o)) ? "open" : "closed";
}
console.log(questionType("Tell me about your last booking"));

